FROM "canc" LEFT JOIN "sbond_2" ON "canc"."drug_id" = "sbond_2"."drug" LEFT JOIN "atom" ON "sbond_2"."atomid_2" = "atom"."atomid" WHERE "sbond_2"."atomid" != 'd206_4                                                                                              ' LIMIT 65;

SELECT "sbond_1"."atomid_2", "atom"."atomtype", "atom"."charge"
FROM "sbond_1" LEFT JOIN "atom" ON "sbond_1"."atomid" = "atom"."atomid" JOIN "sbond_7" ON "atom"."atomid" = "sbond_7"."atomid_2" LIMIT 33;

SELECT "sbond_3"."drug", "sbond_7"."atomid_2", "sbond_3"."atomid", "sbond_3"."drug"
FROM "sbond_7" JOIN "atom" ON "sbond_7"."atomid_2" = "atom"."atomid" JOIN "sbond_3" ON "atom"."atomid" = "sbond_3"."atomid" WHERE "sbond_3"."atomid" = 'd98_14                                                                                              ' LIMIT 79;

